  service: "studio", action: "book", tenant: "orchid", day: "2025-04-02",
  id, units, ...extra
});

function run(script, args, cwd) {
  return spawnSync(process.execPath, [fileURLToPath(new URL(script, import.meta.url)), ...args],
                   {cwd, encoding: "utf8"});
}

function temporary(fn) {
  const dir = mkdtempSync(join(tmpdir(), "studio-quota-"));
  try { fn(dir); } finally { rmSync(dir, {recursive: true, force: true}); }
}

test("Studio quotas accumulate per tenant/day and preserve replay and cancellation", () => {
  const dispatch = planner(catalog);
  const first = booking("first", 7);
  assert.deepEqual(dispatch(first), {status: "booked", id: "first", remaining: 1});
  assert.equal(dispatch(first).status, "replay");
  assert.equal(dispatch({...first, units: 6}).status, "conflict");
  assert.deepEqual(dispatch(booking("extra", 2)), {status: "full", id: "extra", remaining: 1});
  assert.equal(dispatch(booking("other-day", 8, {day: "2025-04-03"})).status, "booked");
  assert.equal(dispatch(booking("iris", 5, {tenant: "iris"})).status, "booked");
  assert.equal(dispatch(booking("iris-extra", 1, {tenant: "iris"})).status, "full");
  assert.equal(dispatch({service: "studio", action: "cancel", id: "first"}).status, "cancelled");
  assert.equal(dispatch(first).status, "cancelled");
  assert.equal(dispatch({...first, units: 6}).status, "conflict");
  assert.equal(dispatch({service: "studio", action: "cancel", id: "first"}).status, "replay");
  assert.deepEqual(dispatch(booking("extra", 2)), {status: "booked", id: "extra", remaining: 6});
  assert.deepEqual(dispatch({service: "studio", action: "usage", tenant: "orchid", day: first.day}),
                   {units: 2});
  assert.equal(dispatch({service: "studio", action: "summary"}).events.length, 5);
});

test("renewals use Studio policy with inherited tenant, overrides, and shared replay semantics", () => {
  const dispatch = planner(catalog);
  dispatch(booking("previous", 7));
  const next = {service: "studio", action: "renew", previous: "previous", id: "next", day: "2025-05-02"};
  assert.deepEqual(dispatch(next), {status: "booked", id: "next", remaining: 1});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units: 6}).status, "conflict");
  assert.deepEqual(dispatch({...next, id: "too-much", units: 2}),
                   {status: "full", id: "too-much", remaining: 1});
  dispatch({service: "studio", action: "cancel", id: "next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch({...next, id: "override", units: 8}).status, "booked");
  assert.deepEqual(apply(dispatch, {...next, id: "invalid", units: 0}), {status: "invalid", field: "units"});
  dispatch({service: "studio", action: "cancel", id: "previous"});
  assert.deepEqual(dispatch(next), {status: "missing", id: "previous"});
});

test("unlisted Studio tenants and both Archive paths retain the catalog default", () => {
