    const next = {service, action: "renew", previous: "seed", id: "renewed", day: "2025-05-02"};
    assert.equal(dispatch({...next, units: 6}).status, "full");
    assert.deepEqual(dispatch(next), {status: "booked", id: "renewed", remaining: 0});
  }
});

